window.__finlexDocLoaded(10134,{"id":10134,"articles":[{"id":1000584,"no":"Overview","heading":"Official Overview & Scope (IFRS Foundation)","text":"SIC-7 clarifies how an entity translates amounts in its financial statements when its functional currency is replaced by the euro.","seq":0},{"id":1000585,"no":"SIC-7.3–4","heading":"Introduction of the Euro","text":"Clarifies that IAS 21 requirements apply strictly to the changeover to the Euro, with FX differences on monetary items recognised in P&L and cumulative translation reserves preserved until disposal.","seq":1},{"id":1000586,"no":"History","heading":"Standard History & Amendments","text":"In April 2001 the International Accounting Standards Board adopted SIC‑7 Introduction of the Euro, which had originally been issued by the Standing Interpretations Committee of the International Accounting Standards Committee in May 1998.\n\nOther Standards have made minor consequential amendments to SIC‑7, including IFRS 9 Financial Instruments (Hedge Accounting and amendments to IFRS 9, IFRS 7 and IAS 39) (issued November 2013).","seq":2},{"id":1000587,"no":"Support","heading":"Related Projects & Implementation Support","text":"[Related IFRS Standards]\n• IAS 21 The Effects of Changes in Foreign Exchange Rates\n\n[Implementation support]\n• SIC-7 Introduction of the Euro","seq":3},{"id":1000588,"no":"References","heading":"Official Text Link & Public Practical Guidance","text":"Official IFRS Foundation Page (English): https://www.ifrs.org/issued-standards/list-of-standards/sic-7-introduction-of-the-euro/\nAccess Note: Free access to the unaccompanied text of IFRS Accounting Standards on ifrs.org requires a free registered IFRS.org account; Basis for Conclusions and Illustrative Examples require an IFRS Digital Subscription.\nPublic Companion Overview: KPMG Insights into IFRS — An Overview (Sept 2026): https://assets.kpmg.com/content/dam/kpmgsites/xx/pdf/ifrg/2026/isg-2026-insights-an-overview.pdf","seq":4}]});
